const items = $input.all();

const ads = items.map(item => {
  const ad = item.json;

  return {
    rank: ad.rank,
    ad_id: ad.ad_id,
    page_name: ad.page_name,
    title: ad.title,
    hook: ad.hook,
    body: ad.body,
    cta: ad.cta,
    video_url: ad.video_url,
    ad_library_url: ad.ad_library_url,

    // Text analysis
    overall_score: ad.overall_score,
    hook_score: ad.hook_score,
    body_score: ad.body_score,
    cta_score: ad.cta_score,
    hook_analysis: ad.hook_analysis,
    body_analysis: ad.body_analysis,
    cta_analysis: ad.cta_analysis,
    target_audience: ad.target_audience,
    strengths: ad.strengths || [],
    weaknesses: ad.weaknesses || [],
    final_recommendation: ad.final_recommendation,

    // Video analysis
    video_hook: ad.video_hook,
    first_3_seconds_visual: ad.first_3_seconds_visual,
    transcript: ad.transcript,
    on_screen_text: ad.on_screen_text || [],
    spoken_cta: ad.spoken_cta,
    creative_summary: ad.creative_summary,
    video_confidence: ad.video_confidence
  };
});

const bestAd = ads[0] || {};

return [{
  json: {
    report_title: "MySivi Facebook Ads Intelligence Report",
    total_ads_analysed: ads.length,
    best_ad: bestAd,
    all_ads: ads,
    important_note:
      "Scores represent AI-based creative quality analysis, not actual conversions or ROAS. Both ad text and video content were analysed using AI."
  }
}];

const incoming = $input.all().filter(item =>
  item.json && item.json.ad_archive_id
);

const ads = incoming.flatMap(item =>
  Array.isArray(item.json) ? item.json : [item.json]
);

return ads.map(ad => {
  const snapshot = ad.snapshot || {};
  const cards = snapshot.cards || [];
  const card = cards[0] || {};

  const videoUrls = cards
    .map(c => c.video_hd_url || c.video_sd_url || "")
    .filter(url => url !== "");

  const videoUrl =
    card.video_hd_url ||
    card.video_sd_url ||
    "";

  return {
    json: {
      ad_id: ad.ad_archive_id || "",
      page_name: ad.page_name || "",
      title: card.title || snapshot.title || "",
      body: card.body || snapshot.body?.text || "",
      hook: card.title || snapshot.title || "",
      cta: card.cta_text || snapshot.cta_text || "",
      video_url: videoUrl,
      video_urls: videoUrls,
      has_video: videoUrls.length > 0,
      ad_library_url: ad.ad_library_url || ""
    }
  };
});

const items = $input.all();
const originalAds = $("Extract Ads Data").all();

function parseJSON(raw, label, index) {
  // If the raw text is empty, null, or undefined, return an empty object instead of crashing
  if (!raw || typeof raw !== "string" || raw.trim() === "") {
    console.warn(`${label} missing or empty at item ${index + 1}, using fallback.`);
    return {};
  }

  const cleaned = raw
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  // If after cleaning it's empty, return an empty object
  if (cleaned === "") {
    return {};
  }

  try {
    return JSON.parse(cleaned);
  } catch (error) {
    console.error(`Failed to parse JSON for ${label} at item ${index + 1}:`, error);
    return {}; // Fallback to an empty object if JSON is malformed
  }
}

const results = items.map((item, index) => {
  const data = item.json;
  const ad = originalAds[index]?.json || {};

  const text = parseJSON(data.text_analysis_raw, "Text Analysis", index);
  const video = parseJSON(data.video_analysis_raw || data.content?.parts?.[0]?.text, "Video Analysis", index);

  return {
    json: {
      ad_id: ad.ad_id || "",
      page_name: ad.page_name || "",
      title: ad.title || "",
      hook: ad.hook || ad.title || "",
      body: ad.body || "",
      cta: ad.cta || "",
      video_url: ad.video_url || "",
      ad_library_url: ad.ad_library_url || "",
      ad_number: index + 1,

      overall_score: Number(text.overall_creative_score || 0),
      hook_score: Number(text.hook_score || 0),
      body_score: Number(text.body_score || 0),
      cta_score: Number(text.cta_score || 0),

      hook_analysis: text.hook_analysis || "",
      body_analysis: text.body_analysis || "",
      cta_analysis: text.cta_analysis || "",
      target_audience: text.target_audience || "",
      strengths: text.strengths || [],
      weaknesses: text.weaknesses || [],
      final_recommendation: text.final_recommendation || "",

      video_hook: video.video_hook || "",
      first_3_seconds_visual: video.first_3_seconds_visual || "",
      transcript: video.transcript || "",
      on_screen_text: video.on_screen_text || [],
      spoken_cta: video.spoken_cta || "",
      creative_summary: video.creative_summary || "",
      video_confidence: video.confidence || ""
    }
  };
});

results.sort((a, b) => b.json.overall_score - a.json.overall_score);

return results.map((item, index) => ({
  json: { rank: index + 1, ...item.json }
}));

const items = $input.all();

return items.map(item => {
  const data = item.json;

  const text = data.content?.parts
    ?.map(part => part.text || "")
    .join("\n") || "";

  return {
    json: {
      text_analysis_raw: text
    }
  };
});

